// ---- weertips: begin (identiek in weer-waarschuwingen.json en 'Daily planning message') ----
// Zet een Open-Meteo-voorspelling om in praktische adviezen. Geeft een lijst regels terug;
// een lege lijst betekent: niets bijzonders te melden.
// Vereist in de API-aanroep: daily=weather_code,temperature_2m_max,temperature_2m_min,
// precipitation_sum,precipitation_probability_max,wind_gusts_10m_max,sunshine_duration,
// snowfall_sum,uv_index_max en hourly=temperature_2m,precipitation,
// precipitation_probability,wind_speed_10m (met timezone=Europe/Amsterdam).
function weerTips(w, nu) {
  if (!w || !w.daily || !w.hourly || !Array.isArray(w.daily.time) || !Array.isArray(w.hourly.time)) {
    throw new Error('Onverwacht antwoord van Open-Meteo: geen daily/hourly gegevens gevonden.');
  }
  const D = w.daily;
  const H = w.hourly;
  const vandaag = nu.toFormat('yyyy-MM-dd');
  const morgen = nu.plus({ days: 1 }).toFormat('yyyy-MM-dd');
  const rond = (x) => Math.round(x);
  const dagIndex = (datum) => D.time.indexOf(datum);
  const dagWaarde = (naam, i) => (D[naam] && i >= 0 && D[naam][i] != null) ? D[naam][i] : null;

  // Vat de uurlijkse gegevens samen over een venster, bijv. de dag of de nacht.
  function venster(vanISO, totISO) {
    let maxKans = null, somRegen = 0, minTemp = null, maxTemp = null, maxWind = null, uren = 0;
    for (let k = 0; k < H.time.length; k++) {
      const t = H.time[k];
      if (t < vanISO || t >= totISO) continue;
      uren++;
      const kans = H.precipitation_probability ? H.precipitation_probability[k] : null;
      const regen = H.precipitation ? H.precipitation[k] : null;
      const temp = H.temperature_2m ? H.temperature_2m[k] : null;
      const wind = H.wind_speed_10m ? H.wind_speed_10m[k] : null;
      if (kans != null) maxKans = maxKans == null ? kans : Math.max(maxKans, kans);
      if (regen != null) somRegen += regen;
      if (temp != null) {
        minTemp = minTemp == null ? temp : Math.min(minTemp, temp);
        maxTemp = maxTemp == null ? temp : Math.max(maxTemp, temp);
      }
      if (wind != null) maxWind = maxWind == null ? wind : Math.max(maxWind, wind);
    }
    return { uren, maxKans, somRegen, minTemp, maxTemp, maxWind };
  }

  const iVandaag = dagIndex(vandaag);
  const dag = venster(vandaag + 'T09:00', vandaag + 'T19:00');
  const nacht = venster(vandaag + 'T21:00', morgen + 'T09:00');
  const dagMorgen = venster(morgen + 'T09:00', morgen + 'T19:00');
  const regels = [];

  // Vannacht: vorst en gladheid
  if (nacht.minTemp != null && nacht.minTemp <= 0) {
    const glad = nacht.somRegen > 0.1;
    regels.push(`❄️ Vannacht vorst (tot ${rond(nacht.minTemp)}°C) — plantjes naar binnen${glad ? ' en pas op voor gladheid vroeg in de ochtend' : ' en denk aan je autoruiten'}.`);
  } else if (nacht.minTemp != null && nacht.minTemp <= 3) {
    regels.push(`🌡️ Vannacht koud (${rond(nacht.minTemp)}°C) — kans op lichte nachtvorst, gevoelige plantjes beter naar binnen.`);
  }

  // Onweer en sneeuw
  const code = dagWaarde('weather_code', iVandaag);
  if (code != null && code >= 95) {
    regels.push('⛈️ Kans op onweer vandaag — haal losse spullen van het balkon of terras.');
  }
  const sneeuw = dagWaarde('snowfall_sum', iVandaag);
  if (sneeuw != null && sneeuw >= 0.5) {
    regels.push(`🌨️ Sneeuw verwacht vandaag (${sneeuw.toFixed(1)} cm).`);
  }

  // Wind
  const stoten = dagWaarde('wind_gusts_10m_max', iVandaag);
  if (stoten != null && stoten >= 90) {
    regels.push(`💨 Storm vandaag (windstoten tot ${rond(stoten)} km/u) — zet tuinmeubels, parasol en trampoline vast.`);
  } else if (stoten != null && stoten >= 60) {
    regels.push(`💨 Harde wind vandaag (windstoten tot ${rond(stoten)} km/u) — zet losse spullen buiten vast.`);
  }

  // Regen versus drooghangweer
  const natVandaag = (dag.maxKans != null && dag.maxKans >= 60) || dag.somRegen >= 1;
  if (natVandaag) {
    regels.push(`🌧️ Regen vandaag (${dag.somRegen.toFixed(1)} mm) — was ophangen is geen goed plan en neem een paraplu mee.`);
  } else if (dag.maxKans != null && dag.maxKans < 15 && dag.maxWind != null && dag.maxWind >= 10 && dag.maxTemp != null && dag.maxTemp >= 15) {
    regels.push(`🧺 Mooi drooghangweer vandaag (${rond(dag.maxTemp)}°C en ${rond(dag.maxWind)} km/u wind).`);
  }

  // Warmte, terrasweer en UV
  const maxTemp = dagWaarde('temperature_2m_max', iVandaag);
  const zon = dagWaarde('sunshine_duration', iVandaag); // in seconden
  if (maxTemp != null && maxTemp >= 30) {
    regels.push(`🥵 Tropisch warm vandaag (${rond(maxTemp)}°C) — zonwering dicht en genoeg drinken.`);
  } else if (maxTemp != null && maxTemp >= 27) {
    regels.push(`🌡️ Warm vandaag (${rond(maxTemp)}°C) — houd de zon buiten en drink genoeg.`);
  } else if (maxTemp != null && maxTemp >= 21 && !natVandaag && zon != null && zon >= 5 * 3600) {
    regels.push(`☀️ Terrasweer vandaag (${rond(maxTemp)}°C en droog).`);
  }
  const uv = dagWaarde('uv_index_max', iVandaag);
  if (uv != null && uv >= 7) {
    regels.push(`🧴 Hoge UV-index (${rond(uv)}) — zonnebrand aan als je langer buiten bent.`);
  }

  // Morgen, alleen als het duidelijk anders wordt dan vandaag
  const natMorgen = (dagMorgen.maxKans != null && dagMorgen.maxKans >= 70) || dagMorgen.somRegen >= 3;
  if (natMorgen && !natVandaag) {
    regels.push(`☔ Morgen wordt het nat (${dagMorgen.somRegen.toFixed(1)} mm) — doe de was liever vandaag.`);
  }

  // Weekendvooruitblik, alleen op donderdag en vrijdag
  if (nu.weekday === 4 || nu.weekday === 5) {
    const mooi = [];
    for (const [naam, weekdag] of [['zaterdag', 6], ['zondag', 7]]) {
      const datum = nu.plus({ days: weekdag - nu.weekday }).toFormat('yyyy-MM-dd');
      const i = dagIndex(datum);
      const t = dagWaarde('temperature_2m_max', i);
      const regen = dagWaarde('precipitation_sum', i);
      const zonUren = dagWaarde('sunshine_duration', i);
      if (t != null && t >= 20 && (regen == null || regen < 1) && (zonUren == null || zonUren >= 4 * 3600)) {
        mooi.push(`${naam} ${rond(t)}°C`);
      }
    }
    if (mooi.length) {
      regels.push(`☀️ Terrasweer dit weekend: ${mooi.join(' en ')} — droog en zonnig.`);
    }
  }

  return regels;
}
// ---- weertips: einde ----

const inst = $('Instellingen weer').first().json;
const chatId = String(inst.chatId || '').trim();
if (!chatId) { return []; } // geen chat-id ingesteld -> stil eindigen
const plaats = String(inst.plaats || '').trim();

const regels = weerTips($input.first().json, $now.setZone('Europe/Amsterdam'));
if (!regels.length) { return []; } // niets bijzonders: geen bericht

const kop = plaats ? `🌦️ Weer in ${plaats}` : '🌦️ Weer vandaag';
return [{ json: { chatId, tekst: `${kop}\n\n${regels.join('\n')}` } }];
